$pdo=app_database();$_SESSION['workflow_csrf']??=bin2hex(random_bytes(24));
function wh(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function wm(mixed $v):string{return number_format((float)$v,0,',',' ').' FCFA';}
$error='';$selectedId=(int)($_GET['bc_id']??$_POST['bc_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!hash_equals((string)$_SESSION['workflow_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Votre session a expiré.');$lines=[];$categories=(array)($_POST['categorie']??[]);$labels=(array)($_POST['designation']??[]);$quantities=(array)($_POST['quantite']??[]);$prices=(array)($_POST['prix_unitaire']??[]);foreach($labels as $i=>$label){if(trim((string)$label)===''&&trim((string)($prices[$i]??''))==='')continue;$lines[]=['category'=>$categories[$i]??'fourniture','label'=>$label,'quantity'=>$quantities[$i]??1,'unit_price'=>$prices[$i]??0];}$imported=(new BudgetLineImporter())->import($_FILES['budget_file']??[]);if($imported){$_SESSION['workflow_import_lines'][$selectedId]=$imported;header('Location: suivi_affaires.php?bc_id='.$selectedId.'&imported=1');exit;}(new SaveBudgetAndPlanning($pdo))->execute($selectedId,$lines,trim((string)($_POST['planning_label']??'')),(string)($_POST['date_debut']??''),(string)($_POST['date_fin']??''),(int)($_SESSION['user_id']??0));unset($_SESSION['workflow_import_lines'][$selectedId]);(new WorkflowRepository($pdo))->refreshNeedRequests();$_SESSION['workflow_csrf']=bin2hex(random_bytes(24));header('Location: suivi_affaires.php?bc_id='.$selectedId.'&saved=1');exit;}catch(Throwable $e){$error=$e->getMessage();}}
$orders=$pdo->query("SELECT bc.id,bc.numero_bc,bc.reference_client,bc.date_reception,c.nom_client,d.numero_devis,o.num_offre FROM bons_commande bc JOIN devis d ON d.id=bc.devis_id LEFT JOIN client c ON c.id_client=bc.client_id LEFT JOIN offre o ON o.id_offre=d.offre_id WHERE d.archived_at IS NULL AND (d.validation_generale=1 OR d.statut_devis='valide') ORDER BY bc.date_reception DESC,bc.id DESC")->fetchAll();$record=null;$budgetLines=[];
if($selectedId>0){$s=$pdo->prepare("SELECT bc.*,c.nom_client,c.code_client,c.logo_client,d.numero_devis,d.date_emission,d.date_expiration,d.delai_livraison_jours,d.total_ht,d.total_ttc,d.statut_devis,o.num_offre,o.reference_offre,o.titre_offre,o.date_offre,o.date_limite_reponse,o.montant_estime,o.statut offre_statut,o.fichier_ao,o.fichier_ao_original,db.id debourse_id,db.montant_fournitures,db.montant_transport,db.statut debourse_statut,p.libelle planning_label,p.date_debut,p.date_fin,feb.id feb_id,feb.numero_feb,feb.date_disponibilite,feb.statut feb_statut,feb.montant_demande FROM bons_commande bc JOIN devis d ON d.id=bc.devis_id LEFT JOIN client c ON c.id_client=bc.client_id LEFT JOIN offre o ON o.id_offre=d.offre_id LEFT JOIN debourses db ON db.bon_commande_id=bc.id LEFT JOIN planning_affaire p ON p.bon_commande_id=bc.id LEFT JOIN fiches_expression_besoin feb ON feb.bon_commande_id=bc.id WHERE bc.id=:id");$s->execute(['id'=>$selectedId]);$record=$s->fetch()?:null;if(isset($_SESSION['workflow_import_lines'][$selectedId])){$budgetLines=array_map(static fn(array $line)=>['categorie'=>$line['category'],'designation'=>$line['label'],'quantite'=>$line['quantity'],'prix_unitaire'=>$line['unit_price']],$_SESSION['workflow_import_lines'][$selectedId]);}elseif($record&&$record['debourse_id']){$s=$pdo->prepare('SELECT * FROM debourse_lignes WHERE debourse_id=:id ORDER BY position,id');$s->execute(['id'=>$record['debourse_id']]);$budgetLines=$s->fetchAll();}}
if(!$budgetLines)$budgetLines=[['categorie'=>'fourniture','designation'=>'','quantite'=>1,'prix_unitaire'=>''],['categorie'=>'transport','designation'=>'','quantite'=>1,'prix_unitaire'=>'']];
