s="fact"><span>Livraison</span><strong><?=wh($record['delai_livraison_jours']?:'—')?> jours</strong></div><div class="fact"><span>Total HT</span><strong><?=wm($record['total_ht'])?></strong></div><div class="fact"><span>Total TTC</span><strong><?=wm($record['total_ttc'])?></strong></div></div></section><section class="timeline-section"><h3><i class="fa-solid fa-3"></i> Bon de commande</h3><div class="facts"><div class="fact"><span>N° interne</span><strong><?=wh($record['numero_bc'])?></strong></div><div class="fact"><span>N° client</span><strong><?=wh($record['reference_client'])?></strong></div><div class="fact"><span>Date du bon</span><strong><?=wh($record['date_commande'])?></strong></div><div class="fact"><span>Réception</span><strong><?=wh($record['date_reception'])?></strong></div><div class="fact"><span>Montant</span><strong><?=wm($record['montant']?:$record['total_ttc'])?></strong></div><?php if($record['fichier']):?><div class="fact"><span>Document</span><strong><a target="_blank" href="<?=wh($record['fichier'])?>"><i class="fa-regular fa-file-lines"></i> Voir le bon</a></strong></div><?php endif;?></div></section></div></section>
<form class="editor-card" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=wh($_SESSION['workflow_csrf'])?>"><input type="hidden" name="bc_id" value="<?=$selectedId?>"><header class="editor-head"><div><h2><i class="fa-solid fa-coins me-2"></i>Lignes du déboursé</h2><p>Ajoutez autant de fournitures et de frais de transport que nécessaire.</p></div><div class="import-actions"><a class="btn btn-sm btn-outline-primary" href="request/modele_debourse_excel.php"><i class="fa-solid fa-download me-1"></i>Modèle Excel</a><label class="btn btn-sm btn-outline-success mb-0"><i class="fa-solid fa-file-excel me-1"></i>Importer<input hidden type="file" name="budget_file" accept=".xls,.xlsx,.csv" onchange="this.form.submit()"></label></div></header><div class="budget-table-wrap"><table class="budget-table"><thead><tr><th>Catégorie</th><th>Désignation</th><th>Quantité</th><th>Prix unitaire</th><th>Montant</th><th></th></tr></thead><tbody id="budgetLines"><?php foreach($budgetLines as $line):?><tr><td><select name="categorie[]"><option value="fourniture" <?=$line['categorie']==='fourniture'?'selected':''?>>Fourniture</option><option value="transport" <?=$line['categorie']==='transport'?'selected':''?>>Transport</option></select></td><td><input name="designation[]" value="<?=wh($line['designation'])?>" placeholder="Désignation précise"></td><td><input class="line-qty" type="number" min="0.01" step="0.01" name="quantite[]" value="<?=wh($line['quantite'])?>"></td><td><input class="line-price" type="number" min="0" step="0.01" name="prix_unitaire[]" value="<?=wh($line['prix_unitaire'])?>" placeholder="0"></td><td class="line-total">0 FCFA</td><td><button class="remove-line" type="button" title="Supprimer"><i class="fa-solid fa-trash"></i></button></td></tr><?php endforeach;?></tbody></table></div><div class="budget-footer"><button class="btn btn-sm btn-outline-primary" id="addLine" type="button"><i class="fa-solid fa-plus me-1"></i>Ajouter une ligne</