(()=>{const body=document.getElementById('budgetLines'),money=new Intl.NumberFormat('fr-FR');if(!body)return;const refresh=()=>{let total=0;body.querySelectorAll('tr').forEach(row=>{const amount=(parseFloat(row.querySelector('.line-qty')?.value)||0)*(parseFloat(row.querySelector('.line-price')?.value)||0);row.querySelector('.line-total').textContent=money.format(amount)+' FCFA';total+=amount});document.getElementById('budgetTotal').textContent=money.format(total)+' FCFA'};body.addEventListener('input',refresh);body.addEventListener('click',event=>{const button=event.target.closest('.remove-line');if(button&&body.rows.length>1){button.closest('tr').remove();refresh()}});document.getElementById('addLine')?.addEventListener('click',()=>{body.insertAdjacentHTML('beforeend','<tr><td><select name="categorie[]"><option value="fourniture">Fourniture</option><option value="transport">Transport</option></select></td><td><input name="designation[]" placeholder="Désignation précise"></td><td><input class="line-qty" type="number" min="0.01" step="0.01" name="quantite[]" value="1"></td><td><input class="line-price" type="number" min="0" step="0.01" name="prix_unitaire[]" placeholder="0"></td><td class="line-total">0 FCFA</td><td><button class="remove-line" type="button"><i class="fa-solid fa-trash"></i></button></td></tr>');refresh()});refresh()})();
